// Use the same resolver as upsert_concepts so imported RIDs are checked in their
// origin space under the publisher's access. An explicitly selected local Source
// is also valid: dependency ordering upserts it before the referencing node.
export const filterAvailableSourceSlotValues = async ({
  sourceSlotByNodeId,
  client,
  spaceId,
  pendingNodeIds,
}: {
  sourceSlotByNodeId: Record<string, string>;
  client: DGSupabaseClient;
  spaceId: number;
  pendingNodeIds: Set<string>;
}): Promise<Record<string, string>> => {
  const sourceIds = [...new Set(Object.values(sourceSlotByNodeId))];
  const availability = await Promise.all(
    sourceIds.map(async (sourceId): Promise<boolean> => {
      if (!isRid(sourceId) && pendingNodeIds.has(sourceId)) return true;
      const { data, error } = await client.rpc(
        "rid_or_local_id_to_concept_db_id",
        { rid: sourceId, default_space_id: spaceId },
      );
      if (error) throw error;
      return data !== null;
    }),
  );
  const available = new Set(sourceIds.filter((_, i) => availability[i]));
  const kept: Record<string, string> = {};
  for (const [nodeInstanceId, sourceId] of Object.entries(sourceSlotByNodeId)) {
    if (available.has(sourceId)) kept[nodeInstanceId] = sourceId;
    else
      console.warn(
        `Source ${sourceId} is not in the database yet; pushing node ${nodeInstanceId} without ${SOURCE_SLOT}`,
      );
  }
  return kept;
};

CREATE OR REPLACE FUNCTION public.rid_to_space_id_and_local_id(rid VARCHAR)
RETURNS public.accessible_resource STRICT STABLE
SET search_path = ''
LANGUAGE plpgsql AS $$
DECLARE
    uri VARCHAR;
    source_local_id VARCHAR;
    source_id BIGINT;
BEGIN
source_local_id := split_part(rid, '/', -1);
IF length(source_local_id) = length(rid) THEN
    RETURN (null, 'Not a Rid')::public.accessible_resource;
END IF;
uri := substr(rid, 1, length(rid) - length(source_local_id) - 1);
IF rid ~ '^orn:\w+\.\w+:.*$' THEN
    uri := concat(split_part(split_part(uri, ':', 2), '.', 1), ':', split_part(uri, ':', 3));
ELSE
    IF rid ~ '^orn:\w+:.*$' THEN
        uri := substr(uri, 5);
    END IF;
END IF;
SELECT id INTO source_id FROM public."Space" where url=uri;
IF source_id IS NULL THEN
    RETURN (null, concat('Cannot find ', uri))::public.accessible_resource;
END IF;
RETURN (source_id, source_local_id);
END;
$$;

CREATE OR REPLACE FUNCTION public.rid_or_local_id_to_concept_db_id(rid VARCHAR, default_space_id BIGINT)
RETURNS BIGINT STRICT STABLE
SET search_path = ''
LANGUAGE plpgsql AS $$
DECLARE r public.accessible_resource;
BEGIN
    r := (SELECT public.rid_to_space_id_and_local_id(rid));
    IF r.space_id IS NULL THEN
        RETURN  (SELECT id FROM public."Concept" WHERE space_id = default_space_id AND source_local_id = rid);
    ELSE
        RETURN (SELECT id FROM public."Concept" WHERE space_id = r.space_id AND source_local_id = r.source_local_id);
    END IF;
END;
$$;
