\set ON_ERROR_STOP off
SELECT 'jsonb_set with NULL value' AS check, jsonb_set('{}'::jsonb, ARRAY['source'], to_jsonb(NULL::bigint)) IS NULL AS returns_null;

CREATE TABLE c (
  source_local_id text PRIMARY KEY,
  reference_content jsonb NOT NULL DEFAULT '{}'::jsonb
);
INSERT INTO c VALUES ('stored', '{"source": 1}');

-- Mirrors the local_reference_content loop: the resolver returns NULL for an unknown ID.
CREATE FUNCTION build_refs(base jsonb, local_refs jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE
  acc jsonb := jsonb_build_object();
  key text; value jsonb; ref_single_val bigint;
BEGIN
  FOR key, value IN SELECT * FROM jsonb_each(local_refs) LOOP
    SELECT (SELECT NULL::bigint) INTO STRICT ref_single_val;
    acc := jsonb_set(acc, ARRAY[key], to_jsonb(ref_single_val));
  END LOOP;
  RETURN base || acc;
END $$;

-- main: base is coalesce(data.reference_content, '{}'), update overwrites
CREATE FUNCTION upsert_main(id text) RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE r jsonb;
BEGIN
  r := build_refs('{}'::jsonb, '{"source": "unknown"}');
  INSERT INTO c VALUES (id, r)
  ON CONFLICT (source_local_id) DO UPDATE SET reference_content = r;
  RETURN 1;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'main row error: (%) %', SQLSTATE, SQLERRM;
  RETURN -2;
END $$;

-- PR #1334: base is coalesce(NULL, '{}') only inside the IF, insert coalesces to '{}', update keeps stored
CREATE FUNCTION upsert_pr(id text) RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE r jsonb;
BEGIN
  r := build_refs('{}'::jsonb, '{"source": "unknown"}');
  INSERT INTO c VALUES (id, coalesce(r, '{}'::jsonb))
  ON CONFLICT (source_local_id) DO UPDATE SET reference_content = coalesce(r, c.reference_content);
  RETURN 1;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'pr row error: (%) %', SQLSTATE, SQLERRM;
  RETURN -2;
END $$;

SELECT 'main insert' AS case, upsert_main('new_main') AS result;
SELECT 'main update' AS case, upsert_main('stored') AS result;
SELECT 'pr insert' AS case, upsert_pr('new_pr') AS result;
SELECT 'pr update' AS case, upsert_pr('stored') AS result;
SELECT * FROM c ORDER BY source_local_id;

